# Generated by manage.py generate_test_cases.
"""Exercise invitation identity independently of attendance and user retention."""

from typing import Any

from django.core.exceptions import ValidationError

from bloomerp.models.communication.conferencing import ConferenceParticipant
from bloomerp.tests.base import (
    BloomerpModelTestCase,
    ExpectedModelException,
    ModelScenario,
)

from .fixtures import ConferenceFixtures


class TestConferenceParticipantModel(ConferenceFixtures, BloomerpModelTestCase):
    model = ConferenceParticipant

    def get_test_scenarios(self) -> list[ModelScenario[ConferenceParticipant]]:
        """Cover missed invitations, duplicate identities and deleted user history."""
        return [
            ModelScenario(
                name="Declining a call does not create attendance",
                preparation=self.prepare,
                create_args=self.participant_args,
                update_args={"invitation_status": "declined"},
                update_validators=self.no_attendance,
            ),
            ModelScenario(
                name="One participant per user and session",
                preparation=self.prepare,
                create_args=self.duplicate_args,
                expected_exceptions=[ExpectedModelException("create", ValidationError)],
            ),
            ModelScenario(
                name="User deletion preserves participant label",
                preparation=self.prepare,
                create_args=self.user_args,
                post_create=self.delete_user,
                create_validators=self.has_retained_label,
            ),
        ]

    def duplicate_args(self) -> dict[str, Any]:
        """Attempt to invite an existing participant twice."""
        return self.participant_args(user=self.user)

    def user_args(self) -> dict[str, Any]:
        """Invite the existing user to a different session."""
        from bloomerp.models.communication.conferencing import ConferenceSession

        session = ConferenceSession.objects.create(room=self.other_room)
        return self.participant_args(session=session, user=self.user)

    def delete_user(self, participant: ConferenceParticipant) -> None:
        """Remove an account without removing conference history."""
        self.user.delete()

    def has_retained_label(self, participant: ConferenceParticipant) -> bool:
        """Confirm nullable user references preserve historical names."""
        participant.refresh_from_db()
        return (
            participant.user_id is None and str(participant) == "Historical participant"
        )

    def no_attendance(self, participant: ConferenceParticipant) -> bool:
        """Confirm invitation responses do not imply a media connection."""
        return not participant.attendances.exists()
